import { DigoAsset } from '@digo-org/digo-api';
import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend } from 'recharts';

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  override render() {
    // Transform time series data: each time point becomes a data point with all company values
    const chartData = this.timeArray?.map((timeLabel, timeIndex) => {
      const dataPoint: any = { name: timeLabel };

      // For each instance (company), add its value at this time point
      this.instances?.forEach((instance) => {
        const companyName = instance.name as string;
        const revenueArray = instance['revenue'] as number[];
        dataPoint[companyName] = revenueArray[timeIndex];
      });

      return dataPoint;
    }) || [];

    return (
      <div style={{
        width: '100%',
        height: '100%',
        backgroundColor: this.globalParameters['background-color'] as string || '#ffffff',
        padding: '20px',
        fontFamily: 'sans-serif',
        boxSizing: 'border-box'
      }}>
        {this.globalParameters['show-title'] && (
          <h2 style={{
            textAlign: 'center',
            margin: '0 0 20px 0',
            fontSize: '24px',
            color: '#1f2937',
            fontWeight: 'bold'
          }}>
            {this.globalParameters['chart-title'] as string || 'Multi-Company Revenue Comparison'}
          </h2>
        )}

        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={chartData}
            margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
          >
            {this.globalParameters['show-grid'] && (
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
            )}

            <XAxis dataKey="name" stroke="#6b7280" />
            <YAxis stroke="#6b7280" />

            {this.globalParameters['show-tooltip'] && (
              <Tooltip formatter={(value: number) => `$${value.toLocaleString()}`} />
            )}

            {this.globalParameters['show-legend'] && <Legend />}

            {this.instances?.map((instance, index) => (
              <Line
                key={instance.id}
                type={this.globalParameters['smooth-curve'] ? 'monotone' : 'linear'}
                dataKey={instance.name as string}
                stroke={instance['company_color'] as string || '#8884d8'}
                strokeWidth={this.globalParameters['stroke-width'] as number || 2}
                dot={this.globalParameters['show-dots']}
                name={instance.name as string}
              />
            ))}
          </LineChart>
        </ResponsiveContainer>
      </div>
    );
  }
}

